"""Export Markdown di ogni prodotto."""
from __future__ import annotations

import json

from .. import db, profili
from ..pipeline import fasi, mapreduce

DICITURA = {"it": "_Generato automaticamente da Sbob: da rileggere._",
            "en": "_Automatically generated by Sbob: please review._"}
TITOLI = {
    "it": {"dispensa": "Dispensa", "mappa": "Mappa mentale", "flashcard": "Flashcard", "autoverifica": "Autoverifica",
           "glossario": "Glossario", "trascritto": "Trascritto", "risposta": "Risposta"},
    "en": {"dispensa": "Study handout", "mappa": "Mind map", "flashcard": "Flashcards", "autoverifica": "Self-assessment",
           "glossario": "Glossary", "trascritto": "Transcript", "risposta": "Answer"},
}


def _l(lav):
    return profili.lingua_prompt(fasi.lingua_prodotti(lav))


def titolo_prodotto(lav: dict, tipo: str) -> str:
    lg = _l(lav)
    if tipo == "tutto":
        return "completo" if lg == "it" else "complete"
    if tipo == "prodotto":
        return profili.profilo(lav["profilo"])["prodotto"][lg]
    return TITOLI[lg][tipo]


def trascritto(lav: dict) -> str:
    bs = mapreduce.battute(db.segmenti(lav["id"]), fasi.etichettatore(lav))
    return "\n\n".join(mapreduce.righe(bs))


def corpo(lav: dict, tipo: str) -> str:
    """Contenuto Markdown del prodotto, senza intestazione."""
    lg = _l(lav)
    if tipo == "trascritto":
        return trascritto(lav)
    raw = db.prodotto(lav["id"], tipo)
    if raw is None:
        raise KeyError(tipo)
    if tipo in ("prodotto", "mappa", "dispensa"):
        return raw
    d = json.loads(raw)
    if tipo == "flashcard":
        return "\n\n".join(f"**{i}. {c['domanda']}**\n\n{c['risposta']}" for i, c in enumerate(d["carte"], 1))
    if tipo == "autoverifica":
        return "\n\n".join(f"### {i}. {q['domanda']}\n\n**{TITOLI[lg]['risposta']}:** {q['risposta']}"
                           for i, q in enumerate(d["domande"], 1))
    if tipo == "glossario":
        intest = "| Termine | Definizione |" if lg == "it" else "| Term | Definition |"
        return intest + "\n|---|---|\n" + "\n".join(
            f"| {t['termine'].replace('|', '/')} | {t['definizione'].replace('|', '/')} |"
            for t in sorted(d["termini"], key=lambda t: t["termine"].lower()))
    raise KeyError(tipo)


ORDINE_COMPLETO = ["dispensa", "prodotto", "mappa", "autoverifica", "glossario", "flashcard", "trascritto"]


def _abbassa_titoli(testo: str) -> str:
    return "\n".join("##" + r if r.startswith("#") else r for r in testo.splitlines())


def completo(lav: dict) -> str:
    """Tutto il lavoro in un unico documento: ogni prodotto disponibile, poi il trascritto."""
    lg = _l(lav)
    parti = [f"# {lav['titolo']}", DICITURA[lg]]
    for tipo in ORDINE_COMPLETO:
        try:
            c = corpo(lav, tipo)
        except (KeyError, TypeError, ValueError):
            continue
        if c.strip():
            parti.append(f"## {titolo_prodotto(lav, tipo)}\n\n{_abbassa_titoli(c)}")
    return "\n\n".join(parti) + "\n"


def documento(lav: dict, tipo: str) -> str:
    if tipo == "tutto":
        return completo(lav)
    lg = _l(lav)
    if tipo == "mappa":  # compatibile con Obsidian/markmap: niente intestazioni aggiunte
        return corpo(lav, tipo) + "\n"
    return f"# {lav['titolo']} — {titolo_prodotto(lav, tipo)}\n\n{DICITURA[lg]}\n\n{corpo(lav, tipo)}\n"
